//! Native Elixir SDK output for Kaji.
//!
//! The plugin accepts Kaji's normalized [`Api`] representation and emits an
//! idiomatic Mix package. Generated clients use Finch for HTTP, Jason for JSON,
//! typed structs for component models, and explicit `{:ok, value}` / `{:error,
//! reason}` results for every operation.

use std::fmt::Write;

use anyhow::{Result, bail};
use kaji_core::{
    AdditionalProperties, Api, GeneratedFile, GeneratedTree, Operation, Schema, SchemaKind,
    SchemaValue, SdkClientStyle,
};
use serde_json::Value;

const NOTICE: &str = "# Generated by Kaji. Do not edit.\n";

/// Generates a self-contained Elixir Mix SDK under `output_dir`.
///
/// The generated SDK owns a named Finch process, configurable via
/// `Client.new/1`, and has no generator-runtime dependency. `package_name`
/// controls the Mix application name when provided; it is otherwise derived
/// from the source API title.
pub fn generate_elixir_sdk(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
) -> Result<GeneratedTree> {
    generate_elixir_sdk_with_style(api, output_dir, package_name, SdkClientStyle::Flat)
}

/// Generates an Elixir SDK with a direct API module or a resource namespace
/// facade.
///
/// [`SdkClientStyle::Flat`] preserves the original `<Sdk>.API.operation/2`
/// output. [`SdkClientStyle::Namespaced`] adds modules such as
/// `<Sdk>.Resources.Contacts.operation/2`, delegating to those typed direct
/// functions while sharing the same normal `Client` value.
pub fn generate_elixir_sdk_with_style(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
    client_style: SdkClientStyle,
) -> Result<GeneratedTree> {
    let root = output_dir.trim_matches('/');
    if root.is_empty() {
        bail!("Elixir SDK output directory cannot be empty");
    }

    let package = package_name
        .filter(|name| !name.trim().is_empty())
        .map(package_slug)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| format!("{}-sdk", package_slug(&api.name)));
    let app = elixir_identifier(&package);
    let module = pascal_case(&package);
    let mut tree = GeneratedTree::default();

    insert(
        &mut tree,
        root,
        "mix.exs",
        render_mix_exs(api, &app, &module),
    )?;
    insert(
        &mut tree,
        root,
        &format!("lib/{app}.ex"),
        render_root_module(&module, client_style),
    )?;
    insert(
        &mut tree,
        root,
        &format!("lib/{app}/application.ex"),
        render_application(&module),
    )?;
    insert(
        &mut tree,
        root,
        &format!("lib/{app}/api_error.ex"),
        render_api_error(api, &module),
    )?;
    insert(
        &mut tree,
        root,
        &format!("lib/{app}/json.ex"),
        render_json(&module),
    )?;
    insert(
        &mut tree,
        root,
        &format!("lib/{app}/client.ex"),
        render_client(&module),
    )?;
    for schema in &api.schemas {
        insert(
            &mut tree,
            root,
            &format!("lib/{app}/models/{}.ex", snake_case(&schema.name)),
            render_model(&module, schema),
        )?;
    }
    insert(
        &mut tree,
        root,
        &format!("lib/{app}/api.ex"),
        render_api(&module, api),
    )?;
    if client_style == SdkClientStyle::Namespaced {
        for resource in operation_groups(api) {
            insert(
                &mut tree,
                root,
                &format!("lib/{app}/resources/{}.ex", snake_case(&resource)),
                render_resource(&module, &resource, api),
            )?;
        }
    }
    insert(
        &mut tree,
        root,
        "README.md",
        render_readme(api, &package, &module, client_style),
    )?;
    insert(
        &mut tree,
        root,
        "STYLE_GUIDE.md",
        render_style_guide(api, &module, client_style),
    )?;
    Ok(tree)
}

fn insert(tree: &mut GeneratedTree, root: &str, path: &str, contents: String) -> Result<()> {
    tree.insert(GeneratedFile::new(format!("{root}/{path}"), contents)?)
}

fn render_mix_exs(api: &Api, app: &str, module: &str) -> String {
    format!(
        "defmodule {module}.MixProject do\n  use Mix.Project\n\n  def project do\n    [\n      app: :{app},\n      version: \"{}\",\n      elixir: \"~> 1.15\",\n      start_permanent: Mix.env() == :prod,\n      deps: deps(),\n      description: \"Generated Elixir SDK for {}\"\n    ]\n  end\n\n  def application do\n    [extra_applications: [:logger, :inets], mod: {{{module}.Application, []}}]\n  end\n\n  defp deps do\n    [\n      {{:finch, \"~> 0.18\"}},\n      {{:jason, \"~> 1.4\"}}\n    ]\n  end\nend\n",
        package_version(&api.version),
        escape_elixir_string(&api.name),
    )
}

fn render_root_module(module: &str, client_style: SdkClientStyle) -> String {
    let resources = if client_style == SdkClientStyle::Namespaced {
        "\n  Resource modules are also available below `Resources`, for example `Resources.Contacts.create_contact(client, body: contact)`."
    } else {
        ""
    };
    format!(
        "{NOTICE}\ndefmodule {module} do\n  @moduledoc \"Generated Kaji SDK entry point.{resources}\"\n\n  alias {module}.Client\n\n  @spec client(keyword()) :: {{:ok, Client.t()}} | {{:error, term()}}\n  def client(options \\\\ []), do: Client.new(options)\nend\n"
    )
}

fn render_application(module: &str) -> String {
    format!(
        "{NOTICE}\ndefmodule {module}.Application do\n  @moduledoc false\n  use Application\n\n  @impl true\n  def start(_type, _args) do\n    Finch.start_link(name: {module}.Finch)\n  end\nend\n"
    )
}

fn render_api_error(api: &Api, module: &str) -> String {
    let mut output = format!(
        "{NOTICE}\ndefmodule {module}.ApiError do\n  @moduledoc \"An HTTP response outside the 2xx range.\"\n  defexception [:status, :body, :headers]\n\n  @type t :: %__MODULE__{{status: pos_integer(), body: term(), headers: list()}}\n\n  @impl true\n  def message(%__MODULE__{{status: status}}), do: \"Kaji API request failed with status #{{status}}\"\nend\n"
    );
    for operation in &api.operations {
        for response in operation
            .responses
            .iter()
            .filter(|response| is_error_status(&response.status))
        {
            let error = declared_error_name(operation, &response.status);
            let _ = writeln!(
                output,
                "\ndefmodule {module}.Errors.{error} do\n  @moduledoc \"Declared {} response for `{}`.\"\n  defexception [:status, :body, :headers]\n\n  @type t :: %__MODULE__{{status: pos_integer(), body: term(), headers: list()}}\n\n  @impl true\n  def message(%__MODULE__{{status: status}}), do: \"Kaji API request failed with status #{{status}}\"\nend",
                escape_elixir_string(&response.status),
                escape_elixir_string(&operation.id),
            );
        }
    }
    output
}

fn render_json(module: &str) -> String {
    format!(
        "{NOTICE}\ndefmodule {module}.JSON do\n  @moduledoc false\n\n  @spec to_wire(term()) :: term()\n  def to_wire(value) when is_list(value), do: Enum.map(value, &to_wire/1)\n  def to_wire(value) when is_map(value) do\n    if is_struct(value) and function_exported?(value.__struct__, :to_map, 1) do\n      value.__struct__.to_map(value)\n    else\n      Map.new(value, fn {{key, item}} -> {{key, to_wire(item)}} end)\n    end\n  end\n  def to_wire(value), do: value\n\n  @spec decode(binary()) :: {{:ok, term()}} | {{:error, term()}}\n  def decode(\"\"), do: {{:ok, nil}}\n  def decode(body), do: Jason.decode(body)\nend\n"
    )
}

fn _render_client_legacy(module: &str) -> String {
    let output = format!(
        "{NOTICE}\ndefmodule {module}.Client do\n  @moduledoc \"Configurable Finch transport for the generated API.\"\n\n  alias {module}.{{ApiError, JSON}}\n\n  @enforce_keys [:base_url]\n  defstruct base_url: nil, api_key: nil, api_key_header: \"authorization\", api_key_prefix: \"Bearer\", headers: [], finch: {module}.Finch, timeout: 30_000\n\n  @type t :: %__MODULE__{{\n    base_url: String.t(),\n    api_key: String.t() | nil,\n    api_key_header: String.t(),\n    api_key_prefix: String.t() | nil,\n    headers: [{{String.t(), String.t()}}],\n    finch: atom(),\n    timeout: timeout()\n  }}\n\n  @spec new(keyword()) :: {{:ok, t()}} | {{:error, :base_url_required}}\n  def new(options \\\\ []) do\n    case Keyword.get(options, :base_url) do\n      value when is_binary(value) and value != \"\" ->\n        {{:ok, %__MODULE__{{\n          base_url: String.trim_trailing(value, \"/\"),\n          api_key: Keyword.get(options, :api_key),\n          api_key_header: Keyword.get(options, :api_key_header, \"authorization\"),\n          api_key_prefix: Keyword.get(options, :api_key_prefix, \"Bearer\"),\n          headers: Keyword.get(options, :headers, []),\n          finch: {module}.Finch,\n          timeout: Keyword.get(options, :timeout, 30_000)\n        }}}}\n\n      _ -> {{:error, :base_url_required}}\n    end\n  end\n\n  @spec required(keyword(), atom()) :: {{:ok, term()}} | {{:error, {{:missing_required_option, atom()}}}}\n  def required(options, key) do\n    case Keyword.fetch(options, key) do\n      {{:ok, value}} when not is_nil(value) -> {{:ok, value}}\n      _ -> {{:error, {{:missing_required_option, key}}}}\n    end\n  end\n\n  @spec request(t(), atom(), String.t(), list(), list(), term()) :: {{:ok, term()}} | {{:error, term()}}\n  def request(client, method, path, query \\\\ [], headers \\\\ [], body \\\\ nil) do\n    url = client.base_url <> path <> encode_query(query)\n    headers = default_headers(client, headers, body)\n    request = Finch.build(method, url, headers, encode_body(body))\n\n    case Finch.request(request, client.finch, receive_timeout: client.timeout) do\n      {{:ok, %Finch.Response{{status: status, body: response, headers: response_headers}}}} when status in 200..299 ->\n        JSON.decode(response)\n\n      {{:ok, %Finch.Response{{status: status, body: response, headers: response_headers}}}} ->\n        body = case JSON.decode(response) do {{:ok, value}} -> value; _ -> response end\n        {{:error, %ApiError{{status: status, body: body, headers: response_headers}}}}\n\n      {{:error, reason}} -> {{:error, reason}}\n    end\n  end\n\n  defp encode_query([]), do: \"\"\n  defp encode_query(query), do: \"?\" <> URI.encode_query(flatten_query(query))\n\n  defp flatten_query(query) do\n    Enum.flat_map(query, fn\n      {{_name, nil}} -> []\n      {{name, values}} when is_list(values) -> Enum.map(values, &{{name, scalar(&1)}})\n      {{name, value}} -> [{{name, scalar(value)}}]\n    end)\n  end\n\n  defp scalar(value) when is_binary(value), do: value\n  defp scalar(value) when is_boolean(value), do: to_string(value)\n  defp scalar(value), do: to_string(value)\n\n  defp default_headers(client, headers, body) do\n    base = [{{\"accept\", \"application/json\"}} | client.headers] ++ headers\n    base = if is_nil(body), do: base, else: [{{\"content-type\", \"application/json\"}} | base]\n\n    case client.api_key do\n      nil -> base\n      \"\" -> base\n      key -> [{{client.api_key_header, credential(client.api_key_prefix, key)}} | base]\n    end\n  end\n\n  defp credential(nil, key), do: key\n  defp credential(\"\", key), do: key\n  defp credential(prefix, key), do: prefix <> \" \" <> key\n  defp encode_body(nil), do: nil\n  defp encode_body(body), do: Jason.encode!(JSON.to_wire(body))\nend\n"
    );
    output.replace(
        &format!("finch: {module}.Finch,"),
        &format!("finch: Keyword.get(options, :finch, {module}.Finch),"),
    )
}

fn render_client(module: &str) -> String {
    format!(
        "{NOTICE}\n{}",
        r#"defmodule __KAJI_MODULE__.Client do
  @moduledoc "Configurable Finch transport with safe retries and lifecycle hooks."

  alias __KAJI_MODULE__.{ApiError, JSON}

  @enforce_keys [:base_url]
  defstruct base_url: nil, api_key: nil, api_key_header: "authorization", api_key_prefix: "Bearer",
            headers: [], finch: __KAJI_MODULE__.Finch, timeout: 30_000,
            max_retries: 2, retry_initial_delay_ms: 250, retry_max_delay_ms: 8_000,
            before_request: nil, after_response: nil, on_error: nil

  @type t :: %__MODULE__{
    base_url: String.t(), api_key: String.t() | nil, api_key_header: String.t(),
    api_key_prefix: String.t() | nil, headers: [{String.t(), String.t()}], finch: atom(),
    timeout: timeout(), max_retries: non_neg_integer(), retry_initial_delay_ms: non_neg_integer(),
    retry_max_delay_ms: non_neg_integer(), before_request: (map() -> any()) | nil,
    after_response: (map() -> any()) | nil, on_error: (term() -> any()) | nil
  }

  @doc "Creates a reusable client. max_retries: 2 yields Kaji's safe three-attempt policy."
  @spec new(keyword()) :: {:ok, t()} | {:error, :base_url_required}
  def new(options \\ []) do
    case Keyword.get(options, :base_url) do
      value when is_binary(value) and value != "" ->
        hooks = Keyword.get(options, :hooks, %{})
        {:ok, %__MODULE__{
          base_url: String.trim_trailing(value, "/"), api_key: Keyword.get(options, :api_key),
          api_key_header: Keyword.get(options, :api_key_header, "authorization"),
          api_key_prefix: Keyword.get(options, :api_key_prefix, "Bearer"),
          headers: Keyword.get(options, :headers, []), finch: Keyword.get(options, :finch, __KAJI_MODULE__.Finch),
          timeout: non_negative(Keyword.get(options, :timeout, 30_000), 30_000),
          max_retries: non_negative(Keyword.get(options, :max_retries, 2), 2),
          retry_initial_delay_ms: non_negative(Keyword.get(options, :retry_initial_delay_ms, 250), 250),
          retry_max_delay_ms: non_negative(Keyword.get(options, :retry_max_delay_ms, 8_000), 8_000),
          before_request: Map.get(hooks, :before_request, Keyword.get(options, :before_request)),
          after_response: Map.get(hooks, :after_response, Keyword.get(options, :after_response)),
          on_error: Map.get(hooks, :on_error, Keyword.get(options, :on_error))
        }}
      _ -> {:error, :base_url_required}
    end
  end

  @spec required(keyword(), atom()) :: {:ok, term()} | {:error, {:missing_required_option, atom()}}
  def required(options, key) do
    case Keyword.fetch(options, key) do
      {:ok, value} when not is_nil(value) -> {:ok, value}
      _ -> {:error, {:missing_required_option, key}}
    end
  end

  @doc "Only idempotent methods, or POST requests with Idempotency-Key, retry automatically."
  @spec request(t(), atom(), String.t(), list(), list(), term(), atom(), atom(), map()) :: {:ok, term()} | {:error, term()}
  def request(client, method, path, query \\ [], headers \\ [], body \\ nil, body_kind \\ :json, response_kind \\ :json, error_types \\ %{}) do
    url = client.base_url <> path <> encode_query(query)
    headers = default_headers(client, headers, body, body_kind, response_kind)
    context = %{method: method, url: url, query: query, headers: headers, body: body}
    notify(client.before_request, context)
    do_request(client, method, url, headers, body, body_kind, response_kind, error_types, context, 0)
  end

  @doc "Returns a lazy stream of decoded server-sent event data values."
  @spec event_stream(t(), atom(), String.t(), list(), list(), term(), atom()) :: {:ok, Enumerable.t()}
  def event_stream(client, method, path, query \\ [], headers \\ [], body \\ nil, body_kind \\ :json) do
    url = client.base_url <> path <> encode_query(query)
    headers = default_headers(client, headers, body, body_kind, :stream)
    request = Finch.build(method, url, headers, encode_body(body, body_kind))
    notify(client.before_request, %{method: method, url: url, query: query, headers: headers, body: body})

    stream =
      Stream.resource(
        fn -> start_sse_request(client, request, self(), make_ref()) end,
        &next_sse_event/1,
        &close_sse_stream/1
      )

    {:ok, stream}
  end

  @doc false
  @spec json_path(term(), String.t()) :: term() | nil
  def json_path(value, path) when is_binary(path) do
    value
    |> JSON.to_wire()
    |> do_json_path(String.trim_leading(path, "$."))
  end

  defp do_json_path(value, ""), do: value
  defp do_json_path(value, path) when is_map(value) do
    [segment | rest] = String.split(path, ".", parts: 2)
    case Map.fetch(value, segment) do
      {:ok, next} -> do_json_path(next, List.first(rest) || "")
      :error -> nil
    end
  end
  defp do_json_path(_value, _path), do: nil

  defp start_sse_request(client, request, parent, ref) do
    {:ok, task} = Task.start(fn ->
      result =
        Finch.stream(request, client.finch, nil, fn
          {:status, status}, acc -> send(parent, {ref, :status, status}); acc
          {:headers, headers}, acc -> send(parent, {ref, :headers, headers}); acc
          {:data, data}, acc -> send(parent, {ref, :data, data}); acc
        end, receive_timeout: client.timeout)
      send(parent, {ref, :done, result})
    end)
    %{ref: ref, task: task, client: client, status: nil, headers: [], buffer: "", done: false}
  end

  defp next_sse_event(%{done: true} = state), do: {:halt, state}
  defp next_sse_event(state) do
    receive do
      {ref, :status, status} when ref == state.ref and status in 200..299 ->
        next_sse_event(%{state | status: status})
      {ref, :status, status} when ref == state.ref ->
        error = %ApiError{status: status, body: nil, headers: state.headers}
        notify(state.client.on_error, error)
        {[{:error, error}], %{state | done: true}}
      {ref, :headers, headers} when ref == state.ref ->
        next_sse_event(%{state | headers: headers})
      {ref, :data, data} when ref == state.ref ->
        {events, buffer} = decode_sse_data(state.buffer, data)
        if events == [], do: next_sse_event(%{state | buffer: buffer}), else: {events, %{state | buffer: buffer}}
      {ref, :done, {:error, reason}} when ref == state.ref ->
        notify(state.client.on_error, reason)
        {[{:error, reason}], %{state | done: true}}
      {ref, :done, _result} when ref == state.ref ->
        {events, _buffer} = decode_sse_data(state.buffer, "\n\n")
        if events == [], do: {:halt, %{state | done: true}}, else: {events, %{state | done: true}}
    after
      state.client.timeout + 1_000 ->
        close_sse_stream(state)
        error = :sse_timeout
        notify(state.client.on_error, error)
        {[{:error, error}], %{state | done: true}}
    end
  end
  defp close_sse_stream(state) do
    if Process.alive?(state.task), do: Process.exit(state.task, :kill)
    :ok
  end

  defp decode_sse_data(buffer, data) do
    frames = String.split(String.replace(buffer <> data, "\r\n", "\n"), "\n\n")
    {complete, [remainder]} = Enum.split(frames, -1)
    events = complete |> Enum.map(&decode_sse_frame/1) |> Enum.reject(&is_nil/1)
    {events, remainder}
  end
  defp decode_sse_frame(frame) do
    payload =
      frame
      |> String.split("\n")
      |> Enum.filter(&String.starts_with?(&1, "data:"))
      |> Enum.map(&String.trim_leading(&1, "data:"))
      |> Enum.join("\n")
      |> String.trim_leading()
    if payload == "", do: nil, else: {:ok, case JSON.decode(payload) do {:ok, value} -> value; _ -> payload end}
  end

  defp do_request(client, method, url, headers, body, body_kind, response_kind, error_types, context, attempt) do
    request = Finch.build(method, url, headers, encode_body(body, body_kind))
    case Finch.request(request, client.finch, receive_timeout: client.timeout) do
      {:ok, %Finch.Response{status: status, headers: response_headers} = response} ->
        if retryable?(method, headers) and transient_status?(status) and attempt < client.max_retries do
          retry_delay(client, attempt, response_headers)
          do_request(client, method, url, headers, body, body_kind, response_kind, error_types, context, attempt + 1)
        else
          notify(client.after_response, %{request: context, status: status, headers: response_headers, body: response.body})
          case status do
            value when value in 200..299 -> decode_response(response.body, response_kind)
            _ ->
              error = error_for(status, response.body, response_headers, error_types)
              notify(client.on_error, error)
              {:error, error}
          end
        end
      {:error, reason} ->
        if retryable?(method, headers) and attempt < client.max_retries do
          retry_delay(client, attempt, [])
          do_request(client, method, url, headers, body, body_kind, response_kind, error_types, context, attempt + 1)
        else
          notify(client.on_error, reason)
          {:error, reason}
        end
    end
  end

  defp error_for(status, response, headers, error_types) do
    body = case JSON.decode(response) do {:ok, value} -> value; _ -> response end
    module = Map.get(error_types, status, Map.get(error_types, :default, ApiError))
    module.exception(status: status, body: body, headers: headers)
  end
  defp decode_response(_response, :void), do: {:ok, nil}
  defp decode_response(response, :binary), do: {:ok, response}
  defp decode_response(response, :text), do: {:ok, response}
  defp decode_response(response, :json), do: JSON.decode(response)

  defp retryable?(method, _headers) when method in [:get, :put, :patch, :delete], do: true
  defp retryable?(:post, headers), do: Enum.any?(headers, fn {name, _} -> String.downcase(name) == "idempotency-key" end)
  defp retryable?(_, _headers), do: false
  defp transient_status?(status), do: status in [408, 429, 500, 502, 503, 504]
  defp retry_delay(client, attempt, headers) do
    server_delay = headers |> header("retry-after") |> parse_retry_after()
    exponential = client.retry_initial_delay_ms * Integer.pow(2, attempt)
    milliseconds = min(server_delay || exponential, client.retry_max_delay_ms)
    if milliseconds > 0, do: Process.sleep(milliseconds)
  end
  defp parse_retry_after(nil), do: nil
  defp parse_retry_after(value) do
    case Integer.parse(value) do
      {seconds, ""} when seconds >= 0 -> seconds * 1_000
      _ ->
        case Float.parse(value) do
          {seconds, ""} when seconds >= 0 -> round(seconds * 1_000)
          _ -> parse_retry_after_http_date(value)
        end
    end
  end
  # RFC 7231 also permits Retry-After as an IMF-fixdate. The generated Mix app
  # includes OTP's :inets application for this parser.
  defp parse_retry_after_http_date(value) do
    case :httpd_util.convert_request_date(String.to_charlist(value)) do
      {{year, month, day}, {hour, minute, second}} ->
        with {:ok, date} <- Date.new(year, month, day),
             {:ok, time} <- Time.new(hour, minute, second),
             {:ok, datetime} <- NaiveDateTime.new(date, time) do
          max(DateTime.to_unix(DateTime.from_naive!(datetime, "Etc/UTC")) - System.os_time(:second), 0) * 1_000
        else
          _ -> nil
        end
      _ -> nil
    end
  rescue
    _ -> nil
  end
  defp header(headers, name), do: Enum.find_value(headers, fn {key, value} -> if String.downcase(key) == name, do: value end)
  defp notify(callback, value) when is_function(callback, 1), do: callback.(value)
  defp notify(_, _), do: :ok
  defp non_negative(value, _default) when is_integer(value) and value >= 0, do: value
  defp non_negative(_value, default), do: default

  defp encode_query([]), do: ""
  defp encode_query(query), do: "?" <> URI.encode_query(flatten_query(query))
  defp flatten_query(query), do: Enum.flat_map(query, fn {_name, nil} -> []; {name, values} when is_list(values) -> Enum.map(values, &{name, scalar(&1)}); {name, value} -> [{name, scalar(value)}] end)
  defp scalar(value) when is_binary(value), do: value
  defp scalar(value), do: to_string(value)
  defp default_headers(client, headers, body, body_kind, response_kind) do
    accept = case response_kind do :json -> "application/json"; :stream -> "text/event-stream"; _ -> "*/*" end
    base = [{"accept", accept} | client.headers] ++ headers
    base = if is_nil(body), do: base, else: [{"content-type", content_type(body_kind)} | base]
    case client.api_key do nil -> base; "" -> base; key -> [{client.api_key_header, credential(client.api_key_prefix, key)} | base] end
  end
  defp content_type(:form), do: "application/x-www-form-urlencoded"
  defp content_type(:binary), do: "application/octet-stream"
  defp content_type(_), do: "application/json"
  defp credential(nil, key), do: key
  defp credential("", key), do: key
  defp credential(prefix, key), do: prefix <> " " <> key
  defp encode_body(nil, _), do: nil
  defp encode_body(body, :binary) when is_binary(body), do: body
  defp encode_body(_body, :binary), do: raise ArgumentError, "binary request bodies must be binaries"
  defp encode_body(body, :form), do: body |> JSON.to_wire() |> URI.encode_query()
  defp encode_body(body, _), do: Jason.encode!(JSON.to_wire(body))
end
"#
    )
    .replace("__KAJI_MODULE__", module)
}

fn render_model(module: &str, schema: &Schema) -> String {
    let type_name = pascal_case(&schema.name);
    let model = format!("{module}.Models.{type_name}");
    match &schema.value.kind {
        SchemaKind::Object {
            fields,
            additional_properties,
        } => {
            let mut output = format!(
                "{NOTICE}\ndefmodule {model} do\n  @moduledoc \"Generated model for {}.\"\n  alias {module}.JSON\n\n",
                escape_elixir_string(&schema.name)
            );
            if fields.iter().any(|field| field.required) {
                let required = fields
                    .iter()
                    .filter(|field| field.required)
                    .map(|field| format!(":{}", elixir_identifier(&field.name)))
                    .collect::<Vec<_>>();
                let _ = writeln!(output, "  @enforce_keys [{}]", required.join(", "));
            }
            let names = fields
                .iter()
                .map(|field| format!(":{}", elixir_identifier(&field.name)))
                .collect::<Vec<_>>();
            let _ = writeln!(output, "  defstruct [{}]", names.join(", "));
            output.push_str("\n  @type t :: %__MODULE__{\n");
            for field in fields {
                let optional = !field.required || field.value.nullable;
                let _ = writeln!(
                    output,
                    "    {}: {}{},",
                    elixir_identifier(&field.name),
                    elixir_type(&field.value, module),
                    if optional { " | nil" } else { "" }
                );
            }
            output.push_str("  }\n\n  @spec to_map(t()) :: map()\n  def to_map(model) do\n    [\n");
            for field in fields {
                let _ = writeln!(
                    output,
                    "      {{\"{}\", model.{}}},",
                    escape_elixir_string(&field.name),
                    elixir_identifier(&field.name)
                );
            }
            output.push_str("    ]\n    |> Enum.reject(fn {_key, value} -> is_nil(value) end)\n    |> Map.new(fn {key, value} -> {key, JSON.to_wire(value)} end)\n  end\n\n  @spec from_map(map()) :: t()\n  def from_map(map) do\n    %__MODULE__{\n");
            for field in fields {
                let access = format!("Map.get(map, \"{}\")", escape_elixir_string(&field.name));
                let _ = writeln!(
                    output,
                    "      {}: {},",
                    elixir_identifier(&field.name),
                    decode_value(&access, &field.value, module)
                );
            }
            output.push_str("    }\n  end\nend\n");
            if matches!(additional_properties, AdditionalProperties::Schema { .. }) {
                output.push_str("\n# Additional properties are retained by the JSON response but are not typed fields.\n");
            }
            output
        }
        _ => format!(
            "{NOTICE}\ndefmodule {model} do\n  @moduledoc \"Generated type for {}.\"\n  @type t :: {}\nend\n",
            escape_elixir_string(&schema.name),
            elixir_type(&schema.value, module)
        ),
    }
}

fn render_api(module: &str, api: &Api) -> String {
    let mut output = format!(
        "{NOTICE}\ndefmodule {module}.API do\n  @moduledoc \"Typed API operations for {}.\"\n\n  alias {module}.Client\n\n",
        escape_elixir_string(&api.name)
    );
    for operation in &api.operations {
        output.push_str(&render_operation(module, api, operation));
    }
    output.push_str("end\n");
    output
}

fn render_resource(module: &str, resource: &str, api: &Api) -> String {
    let mut output = format!(
        "{NOTICE}\ndefmodule {module}.Resources.{resource} do\n  @moduledoc \"Resource-namespaced operations for {resource}.\"\n\n  alias {module}.{{API, Client}}\n"
    );
    for operation in api
        .operations
        .iter()
        .filter(|operation| operation_resource_name(operation) == resource)
    {
        let name = snake_case(&operation.id);
        let _ = writeln!(
            output,
            "\n  @spec {name}(Client.t(), keyword()) :: {{:ok, term()}} | {{:error, term()}}\n  def {name}(client, options \\\\ []), do: API.{name}(client, options)"
        );
        if cursor_pagination(operation).is_some() {
            let _ = writeln!(
                output,
                "\n  @spec {name}_pages(Client.t(), keyword()) :: Enumerable.t()\n  def {name}_pages(client, options \\\\ []), do: API.{name}_pages(client, options)"
            );
        }
    }
    output.push_str("end\n");
    output
}

fn operation_groups(api: &Api) -> Vec<String> {
    let mut groups = api
        .operations
        .iter()
        .map(operation_resource_name)
        .collect::<Vec<_>>();
    groups.sort();
    groups.dedup();
    groups
}

fn operation_resource_name(operation: &Operation) -> String {
    let tag = operation
        .annotations
        .get("tags")
        .and_then(serde_json::Value::as_array)
        .and_then(|tags| tags.first())
        .and_then(serde_json::Value::as_str)
        .or_else(|| {
            operation
                .annotations
                .get("tag")
                .and_then(serde_json::Value::as_str)
        });
    tag.map(pascal_case)
        .unwrap_or_else(|| pascal_case(&path_resource_segment(&operation.path)))
}

fn path_resource_segment(path: &str) -> String {
    path.split('/')
        .filter(|segment| !segment.is_empty() && !segment.starts_with('{'))
        .find(|segment| {
            let lowered = segment.to_ascii_lowercase();
            lowered != "api"
                && lowered != "email"
                && !(lowered.starts_with('v')
                    && lowered.len() > 1
                    && lowered[1..]
                        .chars()
                        .all(|character| character.is_ascii_digit()))
        })
        .unwrap_or("default")
        .into()
}

/// Elixir keeps pagination explicit: a generated pager exists only for a
/// declared string cursor that maps to an existing operation option. The
/// ordinary operation owns query/header/path serialization on every page.
#[derive(Clone, Debug)]
struct CursorPagination {
    parameter_name: String,
    next_cursor_path: String,
}

fn cursor_pagination(operation: &Operation) -> Option<CursorPagination> {
    let extension = operation
        .annotations
        .get("x-kaji-pagination")
        .or_else(|| operation.annotations.get("x-speakeasy-pagination"))?
        .as_object()?;
    if extension.get("type").and_then(Value::as_str) != Some("cursor") {
        return None;
    }
    let input = extension
        .get("inputs")
        .and_then(Value::as_array)?
        .iter()
        .find(|input| input.get("type").and_then(Value::as_str) == Some("cursor"))?
        .as_object()?;
    if !matches!(
        input.get("in").and_then(Value::as_str),
        None | Some("parameters")
    ) {
        return None;
    }
    let parameter_name = input.get("name")?.as_str()?;
    let parameter = operation.parameters.iter().find(|parameter| {
        parameter.name == parameter_name
            && matches!(parameter.location.as_str(), "query" | "header" | "path")
            && parameter
                .schema
                .as_ref()
                .is_some_and(|schema| matches!(schema.kind, SchemaKind::String))
            && (parameter.location != "path" || parameter.required)
    })?;
    Some(CursorPagination {
        parameter_name: elixir_identifier(&parameter.name),
        next_cursor_path: extension
            .get("outputs")?
            .get("nextCursor")?
            .as_str()?
            .to_owned(),
    })
}

fn render_cursor_paginator(operation: &Operation, pagination: &CursorPagination) -> String {
    let name = snake_case(&operation.id);
    format!(
        "  @doc \"Lazily yields declared cursor pages.\"\n  @spec {name}_pages(Client.t(), keyword()) :: Enumerable.t()\n  def {name}_pages(client, options \\\\ []) when is_list(options) do\n    Stream.resource(\n      fn -> {{:next, options}} end,\n      fn\n        :halt -> {{:halt, :halt}}\n        {{:next, current}} ->\n          case {name}(client, current) do\n            {{:ok, response}} ->\n              case Client.json_path(response, {:?}) do\n                cursor when is_binary(cursor) and cursor != \"\" -> {{[{{:ok, response}}], {{:next, Keyword.put(current, :{}, cursor)}}}}\n                _ -> {{[{{:ok, response}}], :halt}}\n              end\n            {{:error, reason}} -> {{[{{:error, reason}}], :halt}}\n          end\n      end,\n      fn _ -> :ok end\n    )\n  end\n\n",
        pagination.next_cursor_path, pagination.parameter_name,
    )
}

fn operation_is_sse(operation: &Operation) -> bool {
    operation.responses.iter().any(|response| {
        response.status.starts_with('2')
            && response
                .media_types
                .iter()
                .any(|media| media.content_type.eq_ignore_ascii_case("text/event-stream"))
    })
}

fn render_operation(module: &str, api: &Api, operation: &Operation) -> String {
    let name = snake_case(&operation.id);
    let return_type = if operation_is_sse(operation) {
        "Enumerable.t()".into()
    } else {
        response_type(api, operation, module)
    };
    let mut output = String::new();
    let _ = writeln!(
        output,
        "  @type {name}_option :: {}",
        operation_option_types(operation, module)
    );
    let _ = writeln!(
        output,
        "  @spec {name}(Client.t(), [{name}_option()]) :: {{:ok, {return_type}}} | {{:error, term()}}"
    );
    let _ = writeln!(
        output,
        "  def {name}(client, options \\\\ []) when is_list(options) do"
    );

    let required = operation
        .parameters
        .iter()
        .filter(|parameter| parameter.required)
        .collect::<Vec<_>>();
    if required.is_empty() && !request_body_required(operation) {
        render_operation_body(&mut output, module, api, operation, 4);
    } else {
        output.push_str("    with ");
        let mut checks = required
            .iter()
            .map(|parameter| {
                let variable = elixir_identifier(&parameter.name);
                format!("{{:ok, {variable}}} <- Client.required(options, :{variable})")
            })
            .collect::<Vec<_>>();
        if request_body_required(operation) {
            checks.push("{:ok, body} <- Client.required(options, :body)".into());
        }
        output.push_str(&checks.join(",\n         "));
        output.push_str(" do\n");
        render_operation_body(&mut output, module, api, operation, 6);
        output.push_str("    end\n");
    }
    output.push_str("  end\n\n");
    if let Some(pagination) = cursor_pagination(operation) {
        output.push_str(&render_cursor_paginator(operation, &pagination));
    }
    output
}

fn render_operation_body(
    output: &mut String,
    module: &str,
    api: &Api,
    operation: &Operation,
    indent: usize,
) {
    let pad = " ".repeat(indent);
    let _ = writeln!(
        output,
        "{pad}path = \"{}\"",
        escape_elixir_string(&operation.path)
    );
    for parameter in operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "path")
    {
        let value = elixir_identifier(&parameter.name);
        let value = if parameter.required {
            value
        } else {
            format!("Keyword.get(options, :{value})")
        };
        let _ = writeln!(
            output,
            "{pad}path = String.replace(path, \"{{{}}}\", URI.encode(to_string({value}), &URI.char_unreserved?/1))",
            escape_elixir_string(&parameter.name),
        );
    }
    let query = operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "query")
        .map(|parameter| {
            let variable = elixir_identifier(&parameter.name);
            let value = if parameter.required {
                variable
            } else {
                format!("Keyword.get(options, :{variable})")
            };
            format!("{{\"{}\", {value}}}", escape_elixir_string(&parameter.name))
        })
        .collect::<Vec<_>>();
    let _ = writeln!(output, "{pad}query = [{}]", query.join(", "));
    let headers = operation
        .parameters
        .iter()
        .filter(|parameter| parameter.location == "header")
        .map(|parameter| {
            let variable = elixir_identifier(&parameter.name);
            let value = if parameter.required {
                variable
            } else {
                format!("Keyword.get(options, :{variable})")
            };
            format!(
                "{{\"{}\", to_string({value})}}",
                escape_elixir_string(&parameter.name)
            )
        })
        .collect::<Vec<_>>();
    let _ = writeln!(output, "{pad}headers = [{}]", headers.join(", "));
    let _ = writeln!(
        output,
        "{pad}headers = headers |> Enum.reject(fn {{_name, value}} -> is_nil(value) end) |> Enum.map(fn {{name, value}} -> {{name, to_string(value)}} end)"
    );
    let body: String = if operation.request_body.is_some() || operation.request_type.is_some() {
        if request_body_required(operation) {
            "body".into()
        } else {
            "Keyword.get(options, :body)".into()
        }
    } else {
        "nil".into()
    };
    let response = response_decode(api, operation, module, "response");
    let body_kind = operation_body_kind(operation);
    let response_kind = operation_response_kind(operation);
    let error_types = operation_error_types(module, operation);
    if operation_is_sse(operation) {
        let _ = writeln!(
            output,
            "{pad}Client.event_stream(client, :{}, path, query, headers, {body}, :{body_kind})",
            operation.method.as_str().to_ascii_lowercase(),
        );
        return;
    }
    let _ = writeln!(
        output,
        "{pad}case Client.request(client, :{}, path, query, headers, {body}, :{body_kind}, :{response_kind}, {error_types}) do",
        operation.method.as_str().to_ascii_lowercase(),
    );
    let _ = writeln!(output, "{pad}  {{:ok, response}} -> {{:ok, {response}}}");
    for response in operation
        .responses
        .iter()
        .filter(|response| is_error_status(&response.status))
    {
        let Some(schema) = response
            .media_types
            .iter()
            .find(|media| media.content_type.contains("json"))
            .or_else(|| response.media_types.first())
            .and_then(|media| media.schema.as_ref())
        else {
            continue;
        };
        let error = declared_error_name(operation, &response.status);
        let decoded = decode_value("reason.body", schema, module);
        let _ = writeln!(
            output,
            "{pad}  {{:error, %{module}.Errors.{error}{{}} = reason}} -> {{:error, %{{reason | body: {decoded}}}}}"
        );
    }
    let _ = writeln!(output, "{pad}  {{:error, reason}} -> {{:error, reason}}");
    let _ = writeln!(output, "{pad}end");
}

fn operation_option_types(operation: &Operation, module: &str) -> String {
    let mut items = operation
        .parameters
        .iter()
        .map(|parameter| {
            let value = parameter
                .schema
                .as_ref()
                .map(|schema| elixir_type(schema, module))
                .unwrap_or_else(|| "term()".into());
            format!("{{:{}, {value}}}", elixir_identifier(&parameter.name))
        })
        .collect::<Vec<_>>();
    if let Some(body) = &operation.request_body {
        let value = if operation_body_kind(operation) == "binary" {
            "binary()".into()
        } else {
            body.media_types
                .iter()
                .find(|media| media.content_type.contains("json"))
                .or_else(|| body.media_types.first())
                .and_then(|media| media.schema.as_ref())
                .map(|schema| elixir_type(schema, module))
                .or_else(|| operation.request_type.as_deref().map(legacy_type))
                .unwrap_or_else(|| "term()".into())
        };
        items.push(format!("{{:body, {value}}}"));
    } else if let Some(request) = operation.request_type.as_deref() {
        items.push(format!("{{:body, {}}}", legacy_type(request)));
    }
    if items.is_empty() {
        "term()".into()
    } else {
        items.join(" | ")
    }
}

fn operation_body_kind(operation: &Operation) -> &'static str {
    operation
        .request_body
        .as_ref()
        .and_then(|body| body.media_types.first())
        .map(|media| match media.content_type.as_str() {
            "application/x-www-form-urlencoded" => "form",
            "application/octet-stream" => "binary",
            _ => "json",
        })
        .unwrap_or("json")
}

fn operation_response_kind(operation: &Operation) -> &'static str {
    let content_type = operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .and_then(|response| response.media_types.first())
        .map(|media| media.content_type.as_str());
    match content_type {
        Some(value) if value == "application/octet-stream" || value.starts_with("image/") => {
            "binary"
        }
        Some(value) if value.starts_with("text/") => "text",
        _ => {
            if operation.response_type == "void" {
                "void"
            } else {
                "json"
            }
        }
    }
}

fn is_error_status(status: &str) -> bool {
    status == "default"
        || status
            .parse::<u16>()
            .is_ok_and(|status| (400..600).contains(&status))
}

fn declared_error_name(operation: &Operation, status: &str) -> String {
    let suffix = if status == "default" {
        "Default".into()
    } else {
        format!("Status{status}")
    };
    format!("{}{}Error", pascal_case(&operation.id), suffix)
}

fn operation_error_types(module: &str, operation: &Operation) -> String {
    let entries = operation
        .responses
        .iter()
        .filter(|response| is_error_status(&response.status))
        .map(|response| {
            let key = response
                .status
                .parse::<u16>()
                .map(|status| status.to_string())
                .unwrap_or_else(|_| ":default".into());
            format!(
                "{key} => {module}.Errors.{}",
                declared_error_name(operation, &response.status)
            )
        })
        .collect::<Vec<_>>();
    if entries.is_empty() {
        "%{}".into()
    } else {
        format!("%{{{}}}", entries.join(", "))
    }
}

fn request_body_required(operation: &Operation) -> bool {
    operation
        .request_body
        .as_ref()
        .map(|body| body.required)
        .unwrap_or(false)
}

fn response_schema(operation: &Operation) -> Option<&SchemaValue> {
    operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .and_then(|response| {
            response
                .media_types
                .iter()
                .find(|media| media.content_type.contains("json"))
        })
        .or_else(|| {
            operation
                .responses
                .iter()
                .find(|response| response.status.starts_with('2'))
                .and_then(|response| response.media_types.first())
        })
        .and_then(|media| media.schema.as_ref())
}

fn response_type(api: &Api, operation: &Operation, module: &str) -> String {
    response_schema(operation)
        .map(|schema| elixir_type(schema, module))
        .unwrap_or_else(|| {
            if operation.response_type == "void" {
                "nil".into()
            } else if api
                .schemas
                .iter()
                .any(|schema| schema.name == operation.response_type)
            {
                format!(
                    "{module}.Models.{}.t()",
                    pascal_case(&operation.response_type)
                )
            } else {
                legacy_type(&operation.response_type)
            }
        })
}

fn response_decode(api: &Api, operation: &Operation, module: &str, value: &str) -> String {
    if let Some(schema) = response_schema(operation) {
        return decode_value(value, schema, module);
    }
    if let Some(schema) = api
        .schemas
        .iter()
        .find(|schema| schema.name == operation.response_type)
    {
        return decode_value(value, &SchemaValue::reference(&schema.name), module);
    }
    value.into()
}

fn decode_value(value: &str, schema: &SchemaValue, module: &str) -> String {
    match &schema.kind {
        SchemaKind::Reference { reference } => format!(
            "case {value} do nil -> nil; map when is_map(map) -> {module}.Models.{}.from_map(map); other -> other end",
            pascal_case(reference.rsplit('/').next().unwrap_or(reference))
        ),
        SchemaKind::Array { items } => format!(
            "Enum.map({value} || [], fn item -> {} end)",
            decode_value("item", items, module)
        ),
        _ => value.into(),
    }
}

fn elixir_type(value: &SchemaValue, module: &str) -> String {
    let base = match &value.kind {
        SchemaKind::Any | SchemaKind::Not { .. } => "term()".into(),
        SchemaKind::Null => "nil".into(),
        SchemaKind::Boolean => "boolean()".into(),
        SchemaKind::Integer => "integer()".into(),
        SchemaKind::Number => "number()".into(),
        SchemaKind::String => {
            if value.enum_values.is_empty() {
                "String.t()".into()
            } else {
                value
                    .enum_values
                    .iter()
                    .filter_map(|item| item.as_str())
                    .map(|item| format!("\"{}\"", escape_elixir_string(item)))
                    .collect::<Vec<_>>()
                    .join(" | ")
            }
        }
        SchemaKind::Array { items } => format!("[{}]", elixir_type(items, module)),
        SchemaKind::Object {
            additional_properties: AdditionalProperties::Schema { value },
            ..
        } => format!(
            "%{{optional(String.t()) => {}}}",
            elixir_type(value, module)
        ),
        SchemaKind::Object { .. } => "map()".into(),
        SchemaKind::Reference { reference } => format!(
            "{module}.Models.{}.t()",
            pascal_case(reference.rsplit('/').next().unwrap_or(reference))
        ),
        SchemaKind::OneOf { variants } | SchemaKind::AnyOf { variants } => variants
            .iter()
            .map(|variant| elixir_type(variant, module))
            .collect::<Vec<_>>()
            .join(" | "),
        SchemaKind::AllOf { .. } => "map()".into(),
    };
    if value.nullable && base != "nil" {
        format!("{base} | nil")
    } else {
        base
    }
}

fn legacy_type(value: &str) -> String {
    match value {
        "void" => "nil".into(),
        "string" => "String.t()".into(),
        "number" => "number()".into(),
        "integer" => "integer()".into(),
        "boolean" => "boolean()".into(),
        "unknown" => "term()".into(),
        value if value.ends_with("[]") => format!("[{}]", legacy_type(&value[..value.len() - 2])),
        value => format!("{}.t()", pascal_case(value)),
    }
}

fn render_readme(api: &Api, package: &str, module: &str, client_style: SdkClientStyle) -> String {
    let operation = api
        .operations
        .first()
        .map(|operation| snake_case(&operation.id))
        .unwrap_or_else(|| "operation".into());
    let resource = operation_groups(api)
        .first()
        .cloned()
        .unwrap_or_else(|| "Default".into());
    let style = match client_style {
        SdkClientStyle::Flat => "flat",
        SdkClientStyle::Namespaced => "namespaced",
    };
    format!(
        "# {package}\n\nGenerated Elixir SDK for {}. This release selected the **{style}** client style.\n\n```elixir\n{{:ok, client}} = {module}.client(base_url: \"https://api.example.com\", api_key: System.get_env(\"API_KEY\"))\n```\n\n## Flat client\n\n```elixir\n{{:ok, result}} = {module}.API.{operation}(client)\n```\n\n## Namespaced client\n\n```elixir\n{{:ok, result}} = {module}.Resources.{resource}.{operation}(client)\n```\n\nThe namespaced example applies to packages generated with `SdkClientStyle::Namespaced`; direct `{module}.API` functions remain available in that mode. The client uses Finch, returns `{{:ok, value}}` on successful HTTP responses, and returns `{{:error, reason}}` for transport or non-2xx API errors. See [STYLE_GUIDE.md](STYLE_GUIDE.md) for selection guidance.\n",
        api.name,
    )
}

fn render_style_guide(api: &Api, module: &str, client_style: SdkClientStyle) -> String {
    let operation = api
        .operations
        .first()
        .map(|operation| snake_case(&operation.id))
        .unwrap_or_else(|| "operation".into());
    let resource = operation_groups(api)
        .first()
        .cloned()
        .unwrap_or_else(|| "Default".into());
    let selected = match client_style {
        SdkClientStyle::Flat => "flat",
        SdkClientStyle::Namespaced => "namespaced",
    };
    format!(
        "# Elixir SDK style guide\n\nThis generated package selected the **{selected}** layout. Both options use the same normal `{module}.Client` value, Finch transport, and typed direct API functions.\n\n## Flat\n\nUse direct functions from the API module.\n\n```elixir\n{{:ok, client}} = {module}.client(base_url: \"https://api.example.com\")\n{{:ok, result}} = {module}.API.{operation}(client)\n```\n\n## Namespaced\n\nUse resource modules to navigate larger APIs. Kaji uses the first OpenAPI tag; when tags are absent it derives the first useful path segment, skipping `v#`, `api`, and `email`.\n\n```elixir\n{{:ok, client}} = {module}.client(base_url: \"https://api.example.com\")\n{{:ok, result}} = {module}.Resources.{resource}.{operation}(client)\n```\n\nSelect the layout during generation with `SdkClientStyle::Flat` or `SdkClientStyle::Namespaced`. Namespaced packages keep the direct `{module}.API` functions too.\n"
    )
}

fn package_slug(value: &str) -> String {
    snake_case(value).replace('_', "-")
}

fn elixir_identifier(value: &str) -> String {
    let mut value = snake_case(value);
    if value.is_empty() {
        value = "value".into();
    }
    if value
        .chars()
        .next()
        .is_some_and(|character| character.is_ascii_digit())
    {
        value.insert_str(0, "value_");
    }
    if matches!(
        value.as_str(),
        "after" | "catch" | "do" | "else" | "end" | "rescue" | "when"
    ) {
        value.push('_');
    }
    value
}

fn snake_case(value: &str) -> String {
    let mut output = String::new();
    let mut prior_lowercase = false;
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            if character.is_ascii_uppercase() && prior_lowercase && !output.ends_with('_') {
                output.push('_');
            }
            output.push(character.to_ascii_lowercase());
            prior_lowercase = character.is_ascii_lowercase() || character.is_ascii_digit();
        } else if !output.is_empty() && !output.ends_with('_') {
            output.push('_');
            prior_lowercase = false;
        }
    }
    output.trim_matches('_').into()
}

fn pascal_case(value: &str) -> String {
    let mut output = String::new();
    let mut uppercase = true;
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            if uppercase {
                output.push(character.to_ascii_uppercase());
                uppercase = false;
            } else {
                output.push(character);
            }
        } else {
            uppercase = true;
        }
    }
    if output.is_empty() {
        "GeneratedSdk".into()
    } else if output
        .chars()
        .next()
        .is_some_and(|character| character.is_ascii_digit())
    {
        format!("Sdk{output}")
    } else {
        output
    }
}

fn package_version(version: &str) -> String {
    let parts = version.split('-').collect::<Vec<_>>();
    if parts.len() == 3 && parts.iter().all(|part| part.parse::<u64>().is_ok()) {
        return parts
            .iter()
            .filter_map(|part| part.parse::<u64>().ok())
            .map(|part| part.to_string())
            .collect::<Vec<_>>()
            .join(".");
    }
    if version.split('.').count() == 3 && version.split('.').all(|part| part.parse::<u64>().is_ok())
    {
        return version.into();
    }
    "0.1.0".into()
}

fn escape_elixir_string(value: &str) -> String {
    value.replace('\\', "\\\\").replace('"', "\\\"")
}

#[cfg(test)]
mod tests {
    use super::*;
    use kaji_core::{Field, HttpMethod, OperationParameter};

    fn api() -> Api {
        Api {
            name: "Example API".into(),
            version: "2026-09-19".into(),
            schemas: vec![Schema::new(
                "Contact",
                SchemaValue::new(SchemaKind::Object {
                    fields: vec![
                        Field {
                            name: "id".into(),
                            value: SchemaValue::new(SchemaKind::String),
                            required: true,
                            annotations: Default::default(),
                        },
                        Field {
                            name: "display-name".into(),
                            value: SchemaValue::new(SchemaKind::String),
                            required: false,
                            annotations: Default::default(),
                        },
                    ],
                    additional_properties: AdditionalProperties::Forbidden,
                }),
            )],
            operations: vec![Operation {
                id: "getContact".into(),
                method: HttpMethod::Get,
                path: "/contacts/{contactId}".into(),
                response_type: "Contact".into(),
                request_type: None,
                parameters: vec![
                    OperationParameter {
                        name: "contactId".into(),
                        location: "path".into(),
                        required: true,
                        schema: Some(SchemaValue::new(SchemaKind::String)),
                        description: None,
                        annotations: Default::default(),
                    },
                    OperationParameter {
                        name: "includeDeleted".into(),
                        location: "query".into(),
                        required: false,
                        schema: Some(SchemaValue::new(SchemaKind::Boolean)),
                        description: None,
                        annotations: Default::default(),
                    },
                ],
                request_body: None,
                responses: vec![],
                security: vec![],
                annotations: Default::default(),
            }],
            annotations: Default::default(),
        }
    }

    #[test]
    fn generates_a_deterministic_typed_mix_package() {
        let first = generate_elixir_sdk(&api(), "sdk/elixir", Some("example-api-sdk")).unwrap();
        let second = generate_elixir_sdk(&api(), "sdk/elixir", Some("example-api-sdk")).unwrap();
        assert_eq!(first, second);
        assert!(
            first
                .get("sdk/elixir/mix.exs")
                .unwrap()
                .contains("app: :example_api_sdk")
        );
        assert!(
            first
                .get("sdk/elixir/mix.exs")
                .unwrap()
                .contains("version: \"2026.9.19\"")
        );
        let model = first
            .get("sdk/elixir/lib/example_api_sdk/models/contact.ex")
            .unwrap();
        assert!(model.contains("defstruct [:id, :display_name]"));
        assert!(model.contains("{\"display-name\", model.display_name}"));
        let client = first
            .get("sdk/elixir/lib/example_api_sdk/client.ex")
            .unwrap();
        assert!(client.contains("Finch.request(request, client.finch"));
        assert!(client.contains("module.exception(status: status"));
        assert!(client.contains("max_retries: 2"));
        assert!(client.contains("retryable?(:post, headers)"));
        assert!(client.contains("transient_status?(status)"));
        assert!(client.contains("before_request"));
        let operations = first.get("sdk/elixir/lib/example_api_sdk/api.ex").unwrap();
        assert!(operations.contains("def get_contact(client, options \\\\ [])"));
        assert!(operations.contains("Client.required(options, :contact_id)"));
        assert!(operations.contains("URI.encode(to_string(contact_id)"));
    }

    #[test]
    fn rejects_empty_output_directory() {
        assert!(generate_elixir_sdk(&api(), "/", None).is_err());
    }

    #[test]
    fn namespaced_style_exports_resource_modules() {
        let mut tagged = api();
        tagged.operations[0]
            .annotations
            .insert("tags".into(), serde_json::json!(["People"]));
        let tree = generate_elixir_sdk_with_style(
            &tagged,
            "sdk/elixir",
            Some("example-api-sdk"),
            SdkClientStyle::Namespaced,
        )
        .unwrap();

        let resources = tree
            .get("sdk/elixir/lib/example_api_sdk/resources/people.ex")
            .unwrap();
        assert!(resources.contains("defmodule ExampleApiSdk.Resources.People"));
        assert!(resources.contains(
            "def get_contact(client, options \\\\ []), do: API.get_contact(client, options)"
        ));
        assert!(
            tree.get("sdk/elixir/STYLE_GUIDE.md")
                .unwrap()
                .contains("## Namespaced")
        );

        let flat = generate_elixir_sdk(&api(), "sdk/elixir", None).unwrap();
        assert!(
            flat.get("sdk/elixir/lib/example_api_sdk/resources/contacts.ex")
                .is_none()
        );
    }

    #[test]
    fn emits_mix_runtime_retries_hooks_media_and_declared_errors() {
        use kaji_core::{OperationMediaType, OperationResponse};

        let mut source = api();
        source.operations[0].method = HttpMethod::Post;
        source.operations[0].parameters.push(OperationParameter {
            name: "Idempotency-Key".into(),
            location: "header".into(),
            required: true,
            schema: Some(SchemaValue::new(SchemaKind::String)),
            description: None,
            annotations: Default::default(),
        });
        source.operations[0].responses = vec![
            OperationResponse {
                status: "200".into(),
                description: None,
                media_types: vec![OperationMediaType {
                    content_type: "application/octet-stream".into(),
                    schema: None,
                }],
            },
            OperationResponse {
                status: "404".into(),
                description: None,
                media_types: vec![OperationMediaType {
                    content_type: "application/json".into(),
                    schema: Some(SchemaValue::reference("Contact")),
                }],
            },
        ];

        let tree = generate_elixir_sdk(&source, "sdk/elixir", Some("example-api-sdk")).unwrap();
        let client = tree
            .get("sdk/elixir/lib/example_api_sdk/client.ex")
            .unwrap();
        let errors = tree
            .get("sdk/elixir/lib/example_api_sdk/api_error.ex")
            .unwrap();
        let operations = tree.get("sdk/elixir/lib/example_api_sdk/api.ex").unwrap();

        assert!(client.contains("Only idempotent methods, or POST requests with Idempotency-Key"));
        assert!(client.contains("status in [408, 429, 500, 502, 503, 504]"));
        assert!(client.contains("headers |> header(\"retry-after\") |> parse_retry_after()"));
        assert!(client.contains("before_request: Map.get(hooks"));
        assert!(client.contains("encode_body(body, :binary) when is_binary(body)"));
        assert!(errors.contains("Errors.GetContactStatus404Error"));
        assert!(
            operations.contains(
                ":json, :binary, %{404 => ExampleApiSdk.Errors.GetContactStatus404Error}"
            )
        );
        assert!(operations.contains("ExampleApiSdk.Models.Contact.from_map(map)"));
    }

    #[test]
    fn emits_explicit_cursor_pagers_and_lazy_sse_streams() {
        use kaji_core::OperationResponse;

        let mut source = api();
        let mut pages = source.operations[0].clone();
        pages.id = "listContacts".into();
        pages.path = "/contacts".into();
        pages
            .parameters
            .retain(|parameter| parameter.location != "path");
        pages.parameters.push(OperationParameter {
            name: "cursor".into(),
            location: "query".into(),
            required: false,
            schema: Some(SchemaValue::new(SchemaKind::String)),
            description: None,
            annotations: Default::default(),
        });
        pages.annotations.insert(
            "x-kaji-pagination".into(),
            serde_json::json!({
                "type": "cursor",
                "inputs": [{"name": "cursor", "in": "parameters", "type": "cursor"}],
                "outputs": {"nextCursor": "$.meta.nextCursor"}
            }),
        );

        let mut events = pages.clone();
        events.id = "watchContacts".into();
        events.path = "/contacts/events".into();
        events.parameters.clear();
        events.annotations.clear();
        events.responses = vec![OperationResponse {
            status: "200".into(),
            description: None,
            media_types: vec![kaji_core::OperationMediaType {
                content_type: "text/event-stream".into(),
                schema: None,
            }],
        }];
        source.operations = vec![pages, events];

        let tree = generate_elixir_sdk(&source, "sdk/elixir", Some("example-api-sdk")).unwrap();
        let client = tree
            .get("sdk/elixir/lib/example_api_sdk/client.ex")
            .unwrap();
        let operations = tree.get("sdk/elixir/lib/example_api_sdk/api.ex").unwrap();
        let mix = tree.get("sdk/elixir/mix.exs").unwrap();

        assert!(operations.contains("def list_contacts_pages(client, options \\\\ [])"));
        assert!(operations.contains("Client.json_path(response, \"$.meta.nextCursor\")"));
        assert!(operations.contains("Keyword.put(current, :cursor, cursor)"));
        assert!(operations.contains("def watch_contacts(client, options \\\\ [])"));
        assert!(operations.contains("Client.event_stream(client, :get, path"));
        assert!(client.contains("def event_stream(client, method, path"));
        assert!(client.contains("Task.start(fn ->"));
        assert!(client.contains("start_sse_request(client, request, self(), make_ref())"));
        assert!(client.contains("Finch.stream(request, client.finch"));
        assert!(!client.contains("{:cont, acc}"));
        assert!(client.contains(":stream -> \"text/event-stream\""));
        assert!(client.contains("defp decode_sse_data"));
        assert!(client.contains("defp parse_retry_after_http_date"));
        assert!(mix.contains("extra_applications: [:logger, :inets]"));
    }
}
